package cn.sixnine.filmlog;

import android.app.*;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.time.LocalDate;
import java.util.*;

/** A staged lab form; only its save action mutates the owning roll. */
final class LabEditor {
    private final Activity activity;
    private final LogStore logs;
    private final LogStore.Roll roll;
    private final Bundle draft;
    private final String action;
    private final Runnable saved,cancelled;
    private Dialog dialog;
    private LinearLayout root,header,form,footer;
    private TextView error;
    private LabEditor(Activity a,LogStore l,LogStore.Roll r,Bundle state,String mode,Runnable save,Runnable cancel){activity=a;logs=l;roll=r;draft=state;action=mode;saved=save;cancelled=cancel;
        if(!draft.containsKey("labInitialized")){draft.putBoolean("labInitialized",true);draft.putBoolean("self",r.lab.equals("自行冲洗"));draft.putString("lab",r.lab.equals("自行冲洗")?"":r.lab);draft.putString("sent",r.sentDate.isEmpty()&&action.equals("send")?LocalDate.now().toString():r.sentDate);draft.putString("received",r.receivedDate.isEmpty()&&action.equals("receive")?LocalDate.now().toString():r.receivedDate);draft.putString("cost",r.labCost);draft.putString("currency",action.equals("send")&&r.currency.isEmpty()&&r.filmCost.isEmpty()&&r.labCost.isEmpty()?"CNY":r.currency);draft.putString("number",r.labNumber);draft.putString("notes",r.labNotes);}
    }
    static Dialog show(Activity a,LogStore logs,LogStore.Roll r,Bundle draft,String mode,Runnable saved,Runnable cancel){LabEditor editor=new LabEditor(a,logs,r,draft,mode,saved,cancel);editor.open();return editor.dialog;}
    private String get(String k){return draft.getString(k,"");}
    private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
    private int color(int id){return activity.getColor(id);}
    private LinearLayout column(){LinearLayout v=new LinearLayout(activity);v.setOrientation(1);return v;}
    private TextView text(String value,int size,int resource){TextView v=new TextView(activity);v.setText(value);v.setTextSize(size);v.setTextColor(color(resource));v.setIncludeFontPadding(false);return v;}
    private GradientDrawable background(int fill,boolean line,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color(fill));d.setCornerRadius(dp(radius));if(line)d.setStroke(dp(1),color(R.color.ui_outline));return d;}
    private void gap(LinearLayout parent,int value){parent.addView(new View(activity),new LinearLayout.LayoutParams(1,dp(value)));}
    private Button button(String label,boolean primary,Runnable run){Button b=UiSpacing.button(activity);b.setText(label);b.setAllCaps(false);b.setTextSize(14);b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(dp(48));b.setPadding(dp(12),dp(8),dp(12),dp(8));b.setStateListAnimator(null);b.setElevation(0);b.setBackgroundTintList(null);b.setTextColor(color(primary?R.color.ui_on_accent:R.color.ui_accent));b.setBackground(background(primary?R.color.ui_accent:R.color.ui_card,!primary,9));b.setOnClickListener(v->run.run());return b;}
    private void hideKeyboard(){if(dialog.getWindow()!=null)((android.view.inputmethod.InputMethodManager)activity.getSystemService(Activity.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(dialog.getWindow().getDecorView().getWindowToken(),0);}
    private void cancel(){hideKeyboard();dialog.dismiss();cancelled.run();}
    private void open(){dialog=new Dialog(activity,R.style.FilmDialog);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);dialog.setOnCancelListener(d->cancel());render();dialog.show();Window w=dialog.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setGravity(Gravity.BOTTOM);fit();root.post(this::fit);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);}}
    private void line(LinearLayout parent){View v=new View(activity);v.setBackgroundColor(color(R.color.ui_outline));parent.addView(v,new LinearLayout.LayoutParams(-1,dp(1)));}
    private EditText field(LinearLayout parent,String label,String key,boolean number){parent.addView(text(label,12,R.color.ui_muted));gap(parent,7);EditText e=new EditText(activity);e.setText(get(key));e.setHint(key.equals("cost")?"未记录":key.equals("lab")?"填写或选择冲洗店":"选填");e.setSingleLine(!key.equals("notes"));e.setTextSize(14);e.setTextColor(color(R.color.ui_ink));e.setHintTextColor(color(R.color.ui_muted));e.setBackgroundTintList(null);e.setBackground(background(R.color.ui_card,true,7));e.setPadding(dp(12),dp(10),dp(12),dp(10));e.setMinHeight(dp(48));e.setTag("lab-"+key);e.setContentDescription(label);if(number)e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);e.setFilters(new InputFilter[]{new InputFilter.LengthFilter(key.equals("notes")?4000:500)});e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){draft.putString(key,s.toString());}public void afterTextChanged(Editable e){}});parent.addView(e,new LinearLayout.LayoutParams(-1,-2));gap(parent,16);return e;}
    private void date(LinearLayout parent,String key,String label){parent.addView(text(label,12,R.color.ui_muted));gap(parent,7);Button value=button(get(key).isEmpty()?"未记录":get(key),false,()->{LocalDate day=get(key).isEmpty()?LocalDate.now():LocalDate.parse(get(key));new DatePickerDialog(activity,(v,y,m,d)->{draft.putString(key,LocalDate.of(y,m+1,d).toString());render();},day.getYear(),day.getMonthValue()-1,day.getDayOfMonth()).show();});value.setTag("lab-"+key);value.setContentDescription(label+"："+get(key));value.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);value.setTextColor(color(R.color.ui_ink));parent.addView(value,new LinearLayout.LayoutParams(-1,-2));gap(parent,16);}
    private void render(){root=column();root.setPadding(dp(20),dp(8),dp(20),dp(16));root.setBackground(background(R.color.ui_background,false,18));header=new LinearLayout(activity);header.setGravity(Gravity.CENTER_VERTICAL);TextView title=text(action.equals("receive")?"确认取回":action.equals("edit")?"编辑冲洗信息":"送去冲洗",19,R.color.ui_ink);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button close=button("取消",false,this::cancel);close.setBackgroundColor(android.graphics.Color.TRANSPARENT);close.setTextColor(color(R.color.ui_muted));header.addView(close,new LinearLayout.LayoutParams(-2,-2));root.addView(header);
        ScrollView sc=new ScrollView(activity);sc.setVerticalScrollBarEnabled(false);form=column();sc.addView(form);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));gap(form,16);form.addView(text(roll.stock,14,R.color.ui_ink));gap(form,4);form.addView(text(roll.camera+" · "+roll.count+" 张曝光",12,R.color.ui_muted));gap(form,20);line(form);gap(form,16);
        boolean receive=action.equals("receive"),self=draft.getBoolean("self");
        if(!receive){LinearLayout modes=new LinearLayout(activity);for(boolean own:new boolean[]{false,true}){LinearLayout cell=column();Button choice=button(own?"自行冲洗":"送到冲洗店",false,()->{hideKeyboard();draft.putBoolean("self",own);render();});choice.setTag(own?"lab-mode-self":"lab-mode-store");choice.setBackgroundColor(android.graphics.Color.TRANSPARENT);choice.setTextColor(color(self==own?R.color.ui_accent:R.color.ui_muted));cell.addView(choice,new LinearLayout.LayoutParams(-1,-2));View underline=new View(activity);underline.setBackgroundColor(color(self==own?R.color.ui_accent:R.color.ui_outline));cell.addView(underline,new LinearLayout.LayoutParams(-1,dp(self==own?2:1)));modes.addView(cell,new LinearLayout.LayoutParams(0,-2,1));}form.addView(modes);gap(form,20);
            if(!self){EditText lab=field(form,"冲洗店","lab",false);ArrayList<String> names=new ArrayList<>();for(LogStore.Roll r:logs.rolls())if(!r.lab.isEmpty()&&!r.lab.equals("自行冲洗")&&!names.contains(r.lab))names.add(r.lab);if(!names.isEmpty()){Button recent=button("最近使用的冲洗店  ›",false,()->new AlertDialog.Builder(activity).setTitle("选择冲洗店").setItems(names.toArray(new String[0]),(d,w)->lab.setText(names.get(w))).setNegativeButton("取消",null).show());recent.setTextSize(12);form.addView(recent);gap(form,16);}}
            date(form,"sent",self?"开始日期":"送洗日期");if(action.equals("edit")&&roll.state.equals("received"))date(form,"received","取回日期");
        }else{form.addView(text("底片已取回？核对日期和最终费用即可。",13,R.color.ui_muted));gap(form,20);date(form,"received","取回日期");}
        LinearLayout amount=new LinearLayout(activity);LinearLayout left=column(),right=column();field(left,receive?"最终费用":"冲洗费用","cost",true);right.addView(text("币种",12,R.color.ui_muted));gap(right,7);Spinner currency=new Spinner(activity);ArrayList<String> codes=new ArrayList<>(Arrays.asList("CNY","USD","JPY","EUR","GBP","HKD","AUD","NZD",""));TreeSet<String> rest=new TreeSet<>();for(Currency c:Currency.getAvailableCurrencies())rest.add(c.getCurrencyCode());for(String c:rest)if(!codes.contains(c))codes.add(c);ArrayList<String> labels=new ArrayList<>();for(String c:codes)labels.add(c.isEmpty()?"未设置":c);currency.setAdapter(new ArrayAdapter<String>(activity,android.R.layout.simple_spinner_dropdown_item,labels){@Override public View getView(int p,View v,ViewGroup group){TextView t=(TextView)super.getView(p,v,group);t.setTextSize(14);t.setTextColor(color(R.color.ui_ink));return t;}@Override public View getDropDownView(int p,View v,ViewGroup group){TextView t=(TextView)super.getDropDownView(p,v,group);t.setTextSize(14);return t;}});currency.setSelection(Math.max(0,codes.indexOf(get("currency"))));currency.setTag("lab-currency");currency.setContentDescription("冲洗费用币种");currency.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int n,long id){draft.putString("currency",codes.get(n));}public void onNothingSelected(AdapterView<?> p){}});FrameLayout currencyBox=new FrameLayout(activity);currencyBox.setBackground(background(R.color.ui_card,true,7));currencyBox.addView(currency,new FrameLayout.LayoutParams(-1,dp(48)));right.addView(currencyBox,new LinearLayout.LayoutParams(-1,dp(48)));LinearLayout.LayoutParams l=new LinearLayout.LayoutParams(0,-2,1);l.rightMargin=dp(12);amount.addView(left,l);amount.addView(right,new LinearLayout.LayoutParams(0,-2,1));form.addView(amount);form.addView(text(receive?"已有费用已带入；留空仍为未记录。":"留空表示未记录，不会计作 0 元。",11,R.color.ui_muted));gap(form,16);
        if(!receive){line(form);LinearLayout more=column();more.setVisibility(draft.getBoolean("more")?View.VISIBLE:View.GONE);Button toggle=button("更多信息（选填）  ＋",false,()->{draft.putBoolean("more",more.getVisibility()!=View.VISIBLE);more.setVisibility(draft.getBoolean("more")?View.VISIBLE:View.GONE);fit();});toggle.setBackgroundColor(android.graphics.Color.TRANSPARENT);toggle.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);toggle.setTextSize(12);form.addView(toggle);if(!self)field(more,"店铺卷号","number",false);field(more,"备注","notes",false);form.addView(more);}
        error=text("",12,R.color.ui_error);error.setTag("lab-error");error.setVisibility(View.GONE);form.addView(error);footer=column();gap(footer,12);line(footer);gap(footer,12);Button save=button(receive?"已取回底片":action.equals("edit")?"保存修改":self?"开始冲洗":"确认送洗",true,this::save);save.setTag("lab-save");footer.addView(save,new LinearLayout.LayoutParams(-1,-2));root.addView(footer);dialog.setContentView(root);if(dialog.isShowing()){fit();root.post(this::fit);}
    }
    // UiSpacing adds margins on attach, so the posted pass measures their final size.
    private void fit(){
        if(dialog.getWindow()==null||form==null)return;int width=activity.getResources().getDisplayMetrics().widthPixels-root.getPaddingLeft()-root.getPaddingRight();int exact=View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),free=View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED);
        header.measure(exact,free);form.measure(exact,free);footer.measure(exact,free);int height=root.getPaddingTop()+root.getPaddingBottom()+header.getMeasuredHeight()+form.getMeasuredHeight()+footer.getMeasuredHeight();int maximum=Math.round(activity.getResources().getDisplayMetrics().heightPixels*.9f);dialog.getWindow().setLayout(-1,Math.min(height,maximum));
    }
    private void save(){try{boolean receive=action.equals("receive"),self=draft.getBoolean("self");String lab=receive?roll.lab:self?"自行冲洗":get("lab");String sent=receive?roll.sentDate:get("sent"),received=receive||action.equals("edit")?get("received"):roll.receivedDate;logs.saveLab(roll.id,roll.state,action,lab,self&&!receive?"":receive?roll.labNumber:get("number"),sent,received,receive?roll.labNotes:get("notes"),get("cost"),get("currency"));hideKeyboard();dialog.dismiss();saved.run();}catch(Exception invalid){error.setVisibility(View.VISIBLE);error.setText(invalid.getMessage()==null?"保存未完成，请核对输入":invalid.getMessage());fit();error.post(()->error.requestRectangleOnScreen(new android.graphics.Rect(0,0,error.getWidth(),error.getHeight()),false));}}
}
